-- Sources checked 2026-09-06.

WITH verified_patches AS (
  SELECT *
  FROM jsonb_to_recordset($patches$
[{"slug":"gpt-6-astra","family":"GPT-6","ga_date":null,"access":"restricted","comparison_data":{"Developer":"OpenAI","Release date":"2026-09-03","API model ID":"gpt-6-astra","Context window":"1.05M tokens","Max output":"128K tokens","Knowledge cutoff":"Apr 30, 2026","Reasoning / effort":"low / medium / high / xhigh / max","Input / 1M tokens":"$10","Cached input / 1M":"$1","Cache write / 1M":"$12.50","Output / 1M tokens":"$50","Long-context surcharge":">272K input: 2× input/cache and 1.5× output for the full request","Text input":"Yes","Image / vision input":"Yes","Audio input":"No","Video input":"No","Text output":"Yes","Image output":"No native image output; image-generation tool supported","Audio output":"No","Video output":"No","Tool / function calling":"Yes","Computer use":"Yes","API access":"Limited rollout; documented in OpenAI API","Product access":"Trusted Access enterprises; API and Plus/Pro/Business/Enterprise rollout","Weights / license":"Restricted proprietary rollout"},"sources":[{"title":"GPT-6 Astra launch","url":"https://openai.com/index/gpt-6-astra/"},{"title":"GPT-6 Astra API model page","url":"https://developers.openai.com/api/docs/models/gpt-6-astra"}],"notes":"Released September 3, 2026 in a staged rollout. Catalog access remains restricted until OpenAI completes general rollout.","metadata":{"launch_stage":"limited_rollout","verification_pass":"astra-fable-muse-gemini-2026-09-06"}},{"slug":"claude-fable-5-1","family":"Claude Fable","ga_date":"2026-09-01","access":"proprietary","comparison_data":{"Developer":"Anthropic","Release date":"2026-09-01","API model ID":"claude-fable-5-1","Context window":"1M tokens","Max output":"128K tokens","Knowledge cutoff":"Jun 2026","Reasoning / effort":"Adaptive thinking (always on); default high; per-message effort","Input / 1M tokens":"$10","Cached input / 1M":"$0.25","Cache write / 1M":"$12.50 (5m) / $20 (1h)","Output / 1M tokens":"$50","Batch / flex discount":"Batch API: 50% off input and output","Text input":"Yes","Image / vision input":"Yes","Audio input":"No","Video input":"No","Text output":"Yes","Image output":"No","Audio output":"No","Video output":"No","Tool / function calling":"Yes","Computer use":"Yes","API access":"Yes","Product access":"Claude API + Amazon Bedrock + Google Cloud + Microsoft Foundry + Claude Platform on AWS","Weights / license":"Proprietary"},"sources":[{"title":"Claude Fable 5.1 model overview","url":"https://platform.claude.com/docs/en/models/fable-5-1/overview"},{"title":"Claude Platform pricing","url":"https://platform.claude.com/docs/en/about-claude/pricing"}],"notes":"Active latest Fable model. Anthropic lists a 1M context window, 128K max output, always-on adaptive thinking, and a June 2026 knowledge cutoff.","metadata":{"launch_stage":"ga","verification_pass":"astra-fable-muse-gemini-2026-09-06"}}]
$patches$::jsonb) AS p(
    slug text, family text, ga_date text, access text,
    comparison_data jsonb, sources jsonb, notes text, metadata jsonb
  )
)
UPDATE models AS m
SET
  family = COALESCE(p.family, m.family),
  ga_date = COALESCE(NULLIF(p.ga_date, '')::date, m.ga_date),
  access = COALESCE(p.access, m.access),
  comparison_data = COALESCE(m.comparison_data, '{}'::jsonb) || COALESCE(p.comparison_data, '{}'::jsonb),
  sources = CASE WHEN p.sources IS NULL OR jsonb_array_length(p.sources) = 0 THEN m.sources ELSE p.sources END,
  notes = COALESCE(p.notes, m.notes),
  metadata = COALESCE(m.metadata, '{}'::jsonb) || COALESCE(p.metadata, '{}'::jsonb),
  verified_at = NOW(),
  updated_at = NOW()
FROM verified_patches AS p
WHERE m.slug = p.slug;

INSERT INTO model_benchmarks (
